{"function":"() => {
const parse=c=>{const m=c.match(/[\d.]+/g);return m?m.map(Number):null};
const lum=([r,g,b])=>{const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)};return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b)};
const bgOf=el=>{let e=el;while(e){const c=parse(getComputedStyle(e).backgroundColor);if(c&&(c.length<4||c[3]>0))return c;e=e.parentElement}return [255,255,255]};
const cr=(a,b)=>{const l1=lum(a),l2=lum(b);return ((Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05)).toFixed(2)};
const out=[];
document.querySelectorAll('#root *').forEach(el=>{
 const t=[...el.childNodes].filter(n=>n.nodeType==3&&n.textContent.trim()).map(n=>n.textContent.trim()).join(' ');
 if(!t)return; const s=getComputedStyle(el); const r=el.getBoundingClientRect(); if(r.width==0)return;
 const fg=parse(s.color); const bg=bgOf(el);
 out.push([el.tagName+'.'+el.className, t.slice(0,30), s.color, 'bg'+bg.join(','), s.fontSize, s.fontWeight, cr(fg,bg), s.opacity]);
});
const ph=[...document.querySelectorAll('input[placeholder]')].map(i=>{const s=getComputedStyle(i,'::placeholder');return [i.id,s.color,s.opacity,bgOf(i).join(','),cr(parse(s.color),bgOf(i))]});
return {out,ph};
}"}

